import random
def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    c = 0
    d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for i, (m, o) in enumerate(history):
        if m == 'C':
            c += 1
        else:
            d += 1
        if m == 'C' and o == 'C':
            cc += 1
        elif m == 'C' and o == 'D':
            cd += 1
        elif m == 'D' and o == 'C':
            dc += 1
        else:
            dd += 1
    if n < 6:
        return 'C'
    last_m, last_o = history[-1]
    if n >= 10:
        recent_defections = 0
        for i in range(n - 5, n):
            if history[i][1] == 'D':
                recent_defections += 1
        if recent_defections >= 4:
            if rng.random() < 0.85:
                return 'D'
            return 'C'
    if n >= 20 and dd > 0:
        opp_def_rate = (cd + dd) / float(n)
        if opp_def_rate > 0.5:
            return 'D'
        if opp_def_rate < 0.15:
            return 'C'
    if n >= 6:
        last_five_opp = [history[i][1] for i in range(max(0, n - 5), n)]
        if all(a == 'D' for a in last_five_opp):
            return 'D'
        if all(a == 'C' for a in last_five_opp):
            if dc > 0 and rng.random() < 0.2:
                return 'D'
            return 'C'
    if last_o == 'D':
        if last_m == 'D':
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        else:
            if rng.random() < 0.6:
                return 'D'
            return 'C'
    else:
        if last_m == 'C':
            if dc > 2 and rng.random() < 0.25:
                return 'D'
            return 'C'
        else:
            return 'C'

